fn parse(s: &str) -> Result<i32, std::num::ParseIntError> { s.parse() }
// ⚠ "会失败"写在返回类型上 —— 调用方忘了处理就编译不过

match parse("42") {
    Ok(n) => println!("{n}"),
    Err(e) => println!("出错了：{e}"),
}

// ⚠ 两条路：可恢复的失败用 Result（是返回值，不是控制流）；
// 不可恢复的用 panic!（用于"程序有 bug"，不是正常错误处理）

